    (hone : ∑ i, c i * x i = 1) : ∀ i, 0 < x i → c i = 1 :=

KInf1:
def KInf1 (Ω : Set V) (avail : Set (V →ᵃ[ℝ] ℝ)) : Prop :=
  IsCompact Ω → Convex ℝ Ω → Nonempty (ElementaryDrivability Ω) →
    SupportingEffectComplete Ω avail
